    public static Definition definition(String code) {
        return DEFINITIONS.stream().filter(item -> item.code().equals(code)).findFirst()
            .orElseThrow(() -> new ApiException(HttpStatus.BAD_REQUEST, "Unsupported report type"));
    }
    private static Metric metric(String code, String km, String en, String definition, String formula, String source, String date, String include, String exclude, String denominator, String currency, String missing) {
        return new Metric(code, km, en, definition, formula, source, date, include, exclude, denominator, currency, missing, VERSION);
    }
    private static Metric countMetric(String code, String km, String en, String source, String calculation, String date, String include, String exclude) {
        return metric(code,km,en,en,calculation,source,date,include,exclude,"none","Not monetary","Zero means no matching persisted records; unavailable is null");
    }
